const ACTD={compra:'Proceso de contratación pública. Se pagan USD 2,5 M al adjudicar (en 2 meses); los repuestos llegan entre 4 y 8 meses después.',emerg:'Más rápida (1–2 meses) pero cuesta USD 3,5 M ya, y la Contraloría puede observarla.',t50:'El Concejo vota hoy mismo. Cuesta 10 de capital político, se apruebe o no.',t60:'Un alza mayor: menos concejales la apoyan. Cuesta 10 de capital político.',transf:'El Alcalde responde hoy.',integ:'Mesa con los operadores privados de buses. Si aceptan: +15 de integración en 6 meses y USD 0,3 M al mes en compensaciones. Cuesta 8 de capital.',loc:'Proceso de contratación: rinde en 3 meses.',campana:'USD 0,3 M. Mejora la aprobación (+4) y el capital político (+3).'};
const ACTS={compra:['Llegan en 4 a 8 meses',['USD 2,5 M al adjudicar']],emerg:['Llegan en 1 a 2 meses',['USD 3,5 M','Riesgo de Contraloría']],t50:['El Concejo vota hoy',['−6 capital político']],t60:['Un alza mayor: menos votos',['−6 capital político']],transf:['El Alcalde responde hoy',[]],integ:['Si aceptan, más pasajeros en 6 meses',['−8 capital político','USD 0,3 M al mes']],campana:['Explica a la ciudad qué cuesta el Metro',['USD 0,3 M','+4 aprobación','+3 capital']],rendicion:['Explicas las cifras ante la ciudad y el Concejo',['USD 0,1 M','+6 capital','+2 aprobación','La oposición lo valora']]};
const HINT={t50:s=>s.pre&&s.mes>12?'Año electoral: casi nadie la vota':'',t60:s=>'',integ:s=>''};
function gauge(p){const c=p>=.6?'#2F9E70':p>=.35?'#D9961C':'#C9424A',r=19,L=2*Math.PI*r;return `<span class="gauge" title="Probabilidad de que acepten"><svg width="50" height="50" viewBox="0 0 50 50"><circle cx="25" cy="25" r="${r}" fill="none" stroke="#E6DCC8" stroke-width="5"/><circle cx="25" cy="25" r="${r}" fill="none" stroke="${c}" stroke-width="5" stroke-dasharray="${(L*p).toFixed(1)} ${L.toFixed(1)}" transform="rotate(-90 25 25)"/></svg><b>${Math.round(p*100)}%</b><small>aceptan</small></span>`}
function actBtn(a,arg){const s=G.s,ok=canAct(s,a,G.ep.acts,arg),pr=probs(s),p={t50:pr.t50,t60:pr.t60,transf:pr.transf,integ:pr.integ}[a];
 const why=s.ap<=0?'Sin fichas este mes':!ok?(a==='compra'?'Ya hay una compra en curso':a==='emerg'?'Solo hasta 2 meses después de una falla grave':(a==='t50'||a==='t60')&&s.tarPend?'Ya hay una tarifa por entrar en vigencia':G.ep.acts&&!G.ep.acts.includes(a)?'Se abre en otro episodio':'No disponible ahora'):'';
 const [d,cost]=ACTS[a]||['',[]],eff=effChips(a,arg),h=HINT[a]?HINT[a](s):'';
 return `<button class="act2" data-act="${a}" ${ok?'':'disabled'}><span class="ai" style="background:${ACT[a][2]}">${ic(ACT[a][1],21,'#fff',2)}</span><span class="atx"><b>${ACT[a][0]}</b><small>${d}</small><span class="chips">${cost.map(c=>`<i class="cc">${c}</i>`).join('')}${eff}</span>${h?`<small class="hint">${ic('arrow',13,'#6B4FC4',2.2)} ${h}</small>`:''}${why?`<small class="whyno">${why}</small>`:''}</span>${p!==undefined?gauge(p):''}<span class="go">${ok?`${ic('bolt',15,'#fff',2.4)} Usar 1 ficha`:'—'}</span></button>`}
function effChips(a,arg){const s=G.s;let mod={};
 if(a==='compra')mod={compra:{inicio:s.mes,llega:s.mes+6,adj:s.mes+2,desierto:false}};
 else if(a==='t50'||a==='t60'){mod={tarPend:{v:a==='t50'?.5:.6,mes:s.mes+2},apr:s.apr-6}}
 else if(a==='integ')mod={integPend:s.integPend+15,integCost:s.integCost+.3};
 else return '';
 const base=project(s,{},6).out[5],alt=project(Object.assign(JSON.parse(JSON.stringify(s)),mod),{},6).out[5],out=[];
 const dc=alt.caja-base.caja,dp=alt.pax-base.pax,ds=alt.salud-base.salud;
 if(Math.abs(dc)>=.1)out.push([`caja ${n1(dc)} M`,dc>0]);if(Math.abs(dp)>=1)out.push([`${n0(dp)} mil pasajeros`,dp>0]);if(Math.abs(ds)>=1)out.push([`estado técnico ${n0(ds)}`,ds>0]);
 return out.length?`<i class="cl">en 6 meses</i>`+out.map(([t_,g])=>`<i class="${g?'cg':'cb'}">${t_}</i>`).join(''):''}
function fmtD(v,unit,dec=0){const t=dec?n1(v):n0(v);return `<b class="${v>0.04?'up':v<-0.04?'dn':''}">${t}${unit}</b>`}
function preview(a,arg){const s=G.s,n=6,base=project(s,{},n).out[n-1];let mod={};
 if(a==='compra')mod={compra:{inicio:s.mes,llega:s.mes+6,adj:s.mes+2,desierto:false}};
 else if(a==='t50'||a==='t60'){const v=a==='t50'?.5:.6;mod={tarPend:{v,mes:s.mes+2},apr:s.apr-6}}
 else if(a==='transf'){const k=arg&&arg.amt!=null?arg.amt:1;mod={transf:s.transf+TRANSF.amt[k],apr:s.apr+TRANSF.apr[k]}}
 else if(a==='integ')mod={integPend:s.integPend+15,integCost:s.integCost+.3};
 else if(a==='loc'){const l=s.loc.slice();l[arg.i]={t:arg.t,until:s.mes+3};mod={loc:l,caja:s.caja-ADS[arg.t].setup}}
 else return '';
 const alt=project(Object.assign(JSON.parse(JSON.stringify(s)),mod),{},n).out[n-1];
 return `Si funciona, en 6 meses: caja ${fmtD(alt.caja-base.caja,' M',1)} · pasajeros ${fmtD(alt.pax-base.pax,' mil')} · aprobación ${fmtD(alt.apr-base.apr,'')}`}
