function spark(arr,col,h=64,w=560,max=100,min=0){if(arr.length<2)return '<p style="color:var(--mute);font-size:14px">Aún no hay historial: cierra algunos meses.</p>';const pts=arr.map((v,i)=>`${(i/(arr.length-1)*w).toFixed(1)},${(h-(v-min)/(max-min)*h).toFixed(1)}`).join(' ');return `<svg width="${w}" height="${h+4}" viewBox="0 -2 ${w} ${h+4}" aria-hidden="true"><polyline points="${pts}" fill="none" stroke="${col}" stroke-width="2.5"/></svg>`}
function optCards(kind){const s=G.s,cur=kind==='mant'?s.mant:s.frec,opts=kind==='mant'?[['r','Recorte','USD 0,6 M/mes'],['n','Normal','USD 1,2 M/mes'],['f','Reforzado','USD 1,8 M/mes']]:[[4,'Cada 4 min','20 trenes'],[5,'Cada 5 min','16 trenes'],[6,'Cada 6 min','13 trenes'],[7,'Cada 7 min','11 trenes']];
 const pr=k=>project(s,kind==='mant'?{mant:k}:{frec:k},6).out[5],base=pr(cur);
 const ch=(v,txt,good)=>`<span class="fc ${good?'g':'b'}">${good?'▲':'▼'} ${txt}</span>`;
 const faces=k=>{if(k==cur)return '<span class="fc n">Lo que tienes hoy</span>';const o=pr(k),dp=o.pax-base.pax,ds=o.salud-base.salud,dc=o.caja-base.caja,r=[];
  if(kind==='frec'&&Math.abs(dp)>=.5)r.push(ch(dp,`${dp>0?'+':'−'}${Math.abs(Math.round(dp))} mil pasajeros`,dp>0));
  if(Math.abs(ds)>=.5)r.push(ch(ds,`${ds>0?'+':'−'}${Math.abs(Math.round(ds))} estado técnico`,ds>0));
  if(Math.abs(dc)>=.05)r.push(ch(dc,`${dc>0?'+':'−'}${money(Math.abs(dc)).replace('USD ','USD ')} en caja`,dc>0));
  return r.join('')};
 return `<div class="opts" style="--n:${opts.length}" id="${kind==='mant'?'prevMant':'prevFrec'}">${opts.map(([k,t,d])=>`<button class="opt" data-${kind}="${k}" aria-pressed="${cur==k}">${cur==k?'<span class="tag2">Actual</span>':''}<b>${t}</b><span style="font-size:13px;color:var(--mute)">${d}</span><div class="prev faces">${faces(k)}</div><small style="font-size:11.5px;color:var(--mute)">en 6 meses</small></button>`).join('')}</div>`}
