function finSummary(s){const e=G.ep,viajes=s.pax*1000*P.dias,inc=[['Pasajes',viajes*s.tarifa*s.tarEf/1e6,'Lo que pagan los pasajeros: '+usd(s.tarifa*s.tarEf)+' en promedio por viaje'],['Publicidad en estaciones',s.otros,'Paneles, pantallas y patrocinios'],['Subsidio municipal',s.transf,'Lo que pone la Alcaldía para cubrir la diferencia']],cost=[['Gastos fijos',costOpOf(s),'Salarios, luz, seguridad, limpieza y servicios'],['Mantenimiento',P.mant[s.mant],'Lo decides en el taller'],['Deuda',P.deuda,'Créditos de construcción: no se puede tocar']];if(s.integCost)cost.push(['Compensación a buses',s.integCost,'Acuerdos de integración']);
 const ti=inc.reduce((a,b)=>a+b[1],0),tc=cost.reduce((a,b)=>a+b[1],0),mx=Math.max(...inc.concat(cost).map(x=>x[1])),pe=projEnd();
 const row=(t,v,d,c,link)=>`<div class="mrow"><span>${t}${link||''}<br><small style="font-weight:500;color:var(--mute);font-size:12px">${d}</small></span><div class="mbar"><i style="width:${v/mx*100}%;background:${c}"></i></div><b style="text-align:right">${v.toFixed(2).replace('.',',')} M</b></div>`;
 const cajaSeries=project(s,{},Math.max(1,e.months-s.mes+1)).out.map(o=>o.caja);
 return `<h3>Este mes, si nada cambia</h3>
  <div class="mk">Ingresos</div>${inc.map(x=>row(x[0],x[1],x[2],'#2F9E70')).join('')}
  <div class="mk" style="margin-top:6px">Gastos</div>${cost.map((x,k)=>row(x[0],x[1],x[2],'#D9534F',k===0?` <button class="link" data-tab="1" style="font-size:12.5px">ver detalle</button>`:'')).join('')}
  <div class="card" style="display:flex;justify-content:space-between;align-items:center"><span><b>Resultado del mes</b><br><span style="font-size:13px;color:var(--mute)">Los pasajes cubren solo el ${Math.round(inc[0][1]/tc*100)}% del gasto</span></span><span class="hd ${ti-tc<0?'dn':'up'}" style="font-weight:600;font-size:26px">${n1(ti-tc)} M</span></div>
  <div class="card"><div style="font-weight:700;font-size:14px;margin-bottom:4px">Caja proyectada hasta el final del episodio: <span class="${pe.caja<0?'dn':'up'}">${money(pe.caja)}</span></div>${spark([s.caja].concat(cajaSeries),pe.caja<0?'#D9534F':'#2F9E70',60,700,Math.max(...cajaSeries,s.caja,1)+1,Math.min(...cajaSeries,s.caja,0)-1)}</div>
  <h3 style="margin-top:4px">¿Cómo mejorar las cuentas?</h3>
  <div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px">${[['Más pasajeros','Conectar los buses','terminal'],['Subir la tarifa','Lo decide el Concejo','concejo'],['Más subsidio','Lo decide el Alcalde','municipio'],['Publicidad','Ingresos en 3 meses','stad'],['Gastos fijos','Seguridad, limpieza, luz','fin1'],['Taller','Frecuencia y mantenimiento','taller']].map(([t,d,id])=>`<div class="card" style="padding:12px 14px"><b>${t}</b><br><span style="font-size:13px;color:var(--mute)">${d}</span><br>${goBtn(id==='stad'?'st':id==='fin1'?'taller':id,'Ir',id)}</div>`).join('')}</div>`}
function openWin(id,tab=0){if(!G)return;if(window.BQ3D)BQ3D.focus(id);if(id==='taller'&&tab===1){id='control';tab=0}{const vw=viewOf(id);if(vw&&vw!==VIEW)setView(vw,1)}const same=!!(G.win&&G.win.id===id&&LAYER().innerHTML);const s=G.s,isSt=/^st\d/.test(id),i=isSt?+id.slice(2):0,w=WIN[isSt?'st':id](s,i);G.win={id,tab};
 const t=w.tabs[Math.min(tab,w.tabs.length-1)];
 show(`<div class="win"><div class="tabs" role="tablist" ${w.tabs.length<2?'style="visibility:hidden"':''}>${w.tabs.map((x,j)=>`<button role="tab" aria-selected="${j===tab}" data-tab="${j}">${x[0]}</button>`).join('')}</div>
 <div class="sheet"><div class="side" style="background:linear-gradient(180deg,${w.theme[0]},${w.theme[1]})"><div style="filter:drop-shadow(0 10px 20px rgba(0,0,0,.4))">${portrait(w.p,96)}</div><div><h2>${w.title}</h2><div class="sub">${w.sub}</div></div><div class="kv">${w.kv.map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}</div><div style="font-size:14px;line-height:1.45;color:#E6ECF8"><b style="display:block;color:#fff">${PEOPLE[w.p].n}</b>${w.quote}</div><div class="sidetok"><span>Fichas este mes</span>${Array.from({length:P.ap},(_,k)=>`<i class="${k<s.ap?'on':''}">${k<s.ap?ic('bolt',13,'#1B2340',2.4):''}</i>`).join('')}</div></div>
 <div class="body">${w.hero||''}${t[1]()}</div></div><button class="xclose wx" data-close aria-label="Cerrar">${ic('x',19,'#fff',2.2)}</button></div>`);if(same&&LAYER().firstElementChild)LAYER().firstElementChild.classList.add('still')}
function subWin(back,backTxt,title,body,w=640){show(`<div class="modal fw" style="width:${w}px"><button class="link" data-goto="${back}" style="font-size:14px">← ${backTxt}</button><h1 style="margin:10px 0 14px;font-size:26px">${title}</h1>${body}</div>`)}
function lagWin(){const s=G.s,H=s.mantHist,L=H.length,arr=[H[L-3],H[L-2],H[L-1],s.mant];
 subWin('taller','Volver al taller','¿Por qué no cambia de inmediato?',`<p style="margin:0 0 18px">Cada decisión tarda <b>3 meses</b> en llegar a los trenes.</p><div class="lagrow">${arr.map((k,i)=>`<div class="lagc ${i===3?'now':''}"><small>${mesName(s.mes+i)}</small><b style="color:${MCOL[k]}">${MLAB[k]}</b>${i===3?'<span>lo que decides hoy</span>':i===0?'<span>llega este mes</span>':''}</div>`).join(`<span class="lagar">${ic('arrow',18,'#9AA6C4',2)}</span>`)}</div>`)}
function bancWin(b){const s=G.s,B=BANC[b],v=s.banc[b],[l,c]=BLAB(v),ok=B.ok(s),ey=Math.round(B.seats*seatP(s,'t50',b)),can=canAct(s,'reunion',G.ep.acts,b);
 subWin('concejo','Volver al Concejo',B.n,`<div style="display:flex;align-items:center;gap:12px;margin-bottom:18px"><span class="bdots">${Array.from({length:B.seats},(_,k)=>`<i style="background:${k<ey?B.col:'#D9CCB0'}"></i>`).join('')}</span><b>${ey} de ${B.seats} a favor del alza</b><span class="mtag" style="color:${c};border-color:${c};margin-left:auto">${l}</span></div>
  <div class="bpost" style="margin-bottom:14px"><span>Relación contigo</span><div class="mbar" style="height:8px"><i style="width:${v}%;background:${B.col}"></i></div><b>${Math.round(v)}</b></div>
  <div style="display:flex;gap:8px;align-items:center;margin-bottom:20px">${ic(ok?'check':'x',18,ok?'#16704F':'#A12B30',2.6)}<span><span style="color:var(--mute)">Piden:</span> ${B.want}</span></div>
  <div style="display:flex;align-items:center;gap:14px"><button class="btn" data-reu="${b}" ${can?'':'disabled'}>${ic('bolt',16,'#fff',2.4)} Reunirse · 1 ficha</button>${ok?'<span style="color:#16704F;font-weight:600;font-size:14px">Rinde el doble ahora</span>':''}</div>`)}
function sheet(icon,title,sub,body,kv){const s=G.s;show(`<div class="win"><div class="sheet"><div class="side"><div style="width:104px;height:104px;border-radius:50%;background:rgba(255,255,255,.08);display:grid;place-items:center;color:#fff">${ic(icon,48,'#fff',1.4)}</div><div><h2>${title}</h2><div class="sub">${sub}</div></div><div class="kv">${(kv||[['Mes',mesName(Math.min(s.mes,G.ep.months))],['Caja',money(s.caja)],['Pasajeros',Math.round(s.pax)+' mil/día']]).map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}</div></div><div class="body"><button class="xclose dark" data-close aria-label="Cerrar">${ic('x',19,'#1B2340',2.2)}</button>${body}</div></div></div>`)}
function goBtn(id,txt,target){return G.ep.bld.includes(id)||id==='taller'?`<button class="link" data-goto="${target||id}">${txt} →</button>`:`<span style="font-size:13px;color:var(--mute);font-weight:600">${ic('lock',13)} Se abre en un episodio posterior</span>`}
function panel(kind){const s=G.s,e=G.ep;if(SIMPLE){if(kind==='fin'||kind==='fin1'){openWin('fin',0);return}if(kind==='apr'||kind==='cap'){felSheet();return}}
 if(kind==='fin'){openCaja();return}
 if(kind==='correo'){openMail();return}
 if(kind==='gallito'){openGallito();return}
 if(kind==='taller'){openWin('taller',0);return}
 if(kind==='pax'){openPax();return}if(kind==='paxold'){const f=[['Tarifa',Math.pow(s.tarifa/P.tar0,P.elast)],['Frecuencia',P.frec[s.frec]],['Integración con buses',1+.8*(s.integ-40)/100],['Confiabilidad',(.7+.3*s.salud/100)/(.7+.3*.85)],['Seguridad, limpieza y luz',1+P.lvDem.seg[s.lv.seg]+P.lvDem.lim[s.lv.lim]+P.lvDem.ene[s.lv.ene]]];
  sheet('users','Pasajeros','Quiénes usan el Metro y por qué',`<h3>${Math.round(s.pax)} mil viajes por día laborable</h3><p>El Metro necesitaría unos 400 mil para cubrir sus costos. Esto empuja o frena la demanda:</p>
   <div style="display:flex;flex-direction:column;gap:8px">${f.map(([t,v])=>`<div class="mrow"><span>${t}</span><div class="mbar"><i style="width:${cl(v*60)}%;background:${v>=1?'#2F9E70':'#D9534F'}"></i></div><b style="text-align:right" class="${v>1.005?'up':v<.995?'dn':''}">${v>=1?'+':'−'}${Math.abs(Math.round((v-1)*100))}%</b></div>`).join('')}</div>
   <h3 style="margin-top:6px">Viajes por estación</h3><div style="display:flex;flex-direction:column;gap:5px">${STN.map((n,i)=>`<div class="mrow" style="grid-template-columns:160px minmax(0,1fr) 60px;font-size:13px"><span>${n}</span><div class="mbar" style="height:9px"><i style="width:${SHARE[i]/25*100}%;background:#2F79E0"></i></div><b style="text-align:right">${(SHARE[i]/STT*s.pax).toFixed(1).replace('.',',')}</b></div>`).join('')}</div>
   <p style="font-size:14px">${goBtn('terminal','Para sumar pasajeros, negocia con los buses')}</p>`);return}
 if(kind==='apr'){sheet('heart','Aprobación ciudadana','Lo que piensa toda la ciudad',`<h3>${Math.round(s.apr)} de 100</h3><p>No es lo mismo que la satisfacción de los usuarios (${Math.round(s.sat)}). La aprobación incluye a quienes nunca usan el Metro y solo ven su costo en las noticias.</p>
   <div class="card"><b>Lo que la sube</b><br><span style="font-size:14px">Un buen servicio, más pasajeros, estaciones seguras y limpias, campañas que explican el Metro.</span></div><div class="card"><b>Lo que la baja</b><br><span style="font-size:14px">Fallas, alzas de tarifa, más subsidio, quejas que nadie atiende y se vuelven virales.</span></div>
   <div class="card"><div style="font-weight:700;margin-bottom:6px;font-size:14px">Mes a mes</div>${spark(s.hist.map(h=>h.apr),'#C9424A')}</div><p style="font-size:14px;display:flex;gap:20px">${goBtn('medios','Ir a medios')}<button class="link" data-win="gallito">Ver Gallito →</button></p>`);return}
 if(kind==='cap'){const sup=Math.round(cl(s.cap)/100*21);sheet('landmark','Capital político','Cuánto te respaldan el Alcalde y el Concejo',`<h3>${Math.round(s.cap)} de 100</h3><p>Es tu crédito con las autoridades. Cada pedido al Concejo o al Municipio lo gasta, se apruebe o no. Sube cuando la ciudad aprueba tu gestión. Si llega a cero, te piden la renuncia.</p>
   <div class="capg"><div class="card"><b style="color:#16704F">Lo sube</b><ul><li>Una rendición de cuentas pública (+6)</li><li>Resolver crisis a tiempo (+3)</li><li>Una campaña de comunicación (+3)</li><li>Una buena aprobación ciudadana, mes a mes</li></ul>${goBtn('concejo','Ir al Concejo')}</div><div class="card"><b style="color:#A12B30">Lo baja</b><ul><li>Cada pedido al Concejo (−6), al Alcalde (−10 a −14) o a los buses (−6), salga bien o no</li><li>Fallas graves y sanciones de la Contraloría</li><li>Una aprobación ciudadana baja</li></ul></div></div><p style="font-size:14px">Para ganar votos en el Concejo, además, trabaja con cada bancada: ${goBtn('concejo','ver las bancadas')}</p>
   <div class="card"><div style="font-weight:700;margin-bottom:6px;font-size:14px">Mes a mes</div>${spark(s.hist.map(h=>h.cap),'#6B4FC4')}</div>`);return}
 if(kind==='hub'){const all=[['taller','Taller y cocheras','Mantenimiento y frecuencia (sin fichas)','taller'],['bodega','Bodega','Comprar repuestos','bodega'],['taller','Gastos fijos','Seguridad, limpieza y luz (sin fichas)','fin1'],['municipio','Municipio','Pedir más subsidio','municipio'],['concejo','Concejo','Pedir alza de tarifa','concejo'],['terminal','Terminal de buses','Integrar buses','terminal'],['medios','Medios','Campaña de comunicación','medios'],['st','Estaciones','Publicidad y reparaciones','stad']];
  sheet('compass','Qué puedo hacer','Todas tus opciones, en un solo lugar',`<h3>Tienes ${s.ap} de ${P.ap} fichas de acción este mes</h3><p>Cada acción grande usa 1 ficha y ocurre de inmediato. Ajustar el taller, los gastos fijos y reparar estaciones no usa fichas. Cuando termines, cierra el mes.</p>
   <div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px">${all.map(([id,t,d,go])=>{const u=e.bld.includes(id)||id==='taller',st=u&&id!=='st'&&go!=='fin1'?bStatus(id):'ok';return `<div class="card" style="display:flex;gap:12px;align-items:center;${u?'':'opacity:.55'}"><i style="width:12px;height:12px;border-radius:50%;background:${u?SCOL[st]:'#CFC4AE'};flex:none"></i><div style="flex:1"><b>${t}</b><br><span style="font-size:13px;color:var(--mute)">${d}</span></div>${u?`<button class="btnp" data-goto="${go}">Ir</button>`:`<span style="font-size:12px;color:var(--mute)">${ic('lock',14)}</span>`}</div>`}).join('')}</div>`);return}
 if(kind==='informes'){sheet('doc','Informes','Archivo de la gerencia',`<h3>Informes mensuales</h3>${G.reports.length?`<div class="list">${G.reports.map((r,i)=>`<div class="li" style="display:flex;justify-content:space-between;align-items:center"><span><b style="text-transform:capitalize">${mesName(r.m)}${r.m>12?' · año 2':''}</b>Caja ${money(r.cur.caja)} · ${Math.round(r.cur.pax)} mil pasajeros</span><button class="btnp" data-rep="${i}">Abrir</button></div>`).reverse().join('')}</div>`:'<p>Aún no hay informes. Se archivan al cerrar cada mes.</p>'}`);return}
 if(kind==='ficha'){const f=s.hist.filter(h=>h.falla).length,ok=s.sol.filter(x=>x.ok).length;sheet('id','Mi ficha','Gerente del Metro',`<h3>Tu gestión hasta ahora</h3><div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px">${[['Meses en el cargo',s.hist.length],['Acciones tomadas',s.acts.length],['Fallas',f],['Fallas graves',s.graves],['Pedidos aprobados',ok+' de '+s.sol.length],['Dilemas resueltos',G.used.length],['Quejas virales',s.virales],['Correos resueltos',G.mail.filter(x=>x.res&&mailOpen(x)).length],['Publicidad activa',s.loc.filter(l=>l&&l.on).length+' estaciones']].map(([a,b])=>`<div class="card"><span class="hd" style="font-weight:600;font-size:28px">${b}</span><br><span style="font-size:13px;color:var(--mute);font-weight:600">${a}</span></div>`).join('')}</div><p style="font-size:14px;color:var(--mute)">Estrellas acumuladas en todos los episodios: ${totalStars()} de 12.</p>`);return}
}
function hemi(yes,anim){const rows=[[9,150],[7,114],[5,78]];let o='',k=0;for(const [n,r] of rows){for(let i=0;i<n;i++){const a=Math.PI*(.06+.88*(i/(n-1))),x=180-r*Math.cos(a),y=172-r*Math.sin(a);o+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="11" fill="${anim?'#D9CCB0':k<yes?'#2F9E70':'#D9534F'}" ${anim?`data-seat="${k}"`:''}/>`;k++}}return `<svg width="360" height="200" viewBox="0 0 360 200" aria-hidden="true">${o}<text x="180" y="196" text-anchor="middle" font-family="Inter" font-weight="600" font-size="13" fill="#5B6584">Se necesitan 11 votos de 21</text></svg>`}
